package com.doctoolkit.config;
import org.springframework.beans.factory.annotation.Value; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component; import java.io.*; import java.nio.file.*; import java.time.*;
@Component public class TempCleanupJob { @Value("${doctoolkit.temp-dir}") Path tempDir; @Value("${doctoolkit.cleanup-minutes}") long minutes; @Scheduled(fixedDelayString="PT10M") public void cleanup() throws IOException { if(!Files.exists(tempDir)) return; Instant cutoff=Instant.now().minus(Duration.ofMinutes(minutes)); try(var s=Files.walk(tempDir)){s.filter(Files::isRegularFile).filter(p->{try{return Files.getLastModifiedTime(p).toInstant().isBefore(cutoff);}catch(IOException e){return false;}}).forEach(p->{try{Files.deleteIfExists(p);}catch(IOException ignored){}});} } }
